'use strict';
const $=id=>document.getElementById(id);let queue=[],running=false,stopping=false,ready=false;
function summary(){const counts=queue.reduce((a,b)=>(a[b.status]=(a[b.status]||0)+1,a),{});$('summary').textContent=queue.length?`${queue.length} files · ${counts.added||0} added · ${counts.skipped||0} already present · ${counts.error||0} failed · ${counts.waiting||0} waiting`:'No books selected.';$('start').disabled=running||!ready||!queue.some(x=>x.status==='waiting');$('clear').disabled=running||!queue.length;$('retry').hidden=running||!queue.some(x=>x.status==='error');$('stop').hidden=!running;$('overall').hidden=!queue.length;$('overall').max=queue.length||1;$('overall').value=queue.filter(x=>['added','skipped','error'].includes(x.status)).length;$('browse').hidden=!queue.some(x=>x.status==='added');}
function state(item,status,detail){item.status=status;item.el.className='item '+status;item.state.textContent={waiting:'Waiting',uploading:'Uploading',processing:'Processing',added:'Added',skipped:'Already present',error:'Failed'}[status];item.detail.textContent=detail||'';item.progress.hidden=!['uploading','processing'].includes(status);if(status==='processing')item.progress.removeAttribute('value');summary();}
function select(files){if(running)return;let ignored=0;for(const file of files){if(!/\.(epub|pdf|mobi)$/i.test(file.name)){ignored++;continue}const key=[file.name,file.size,file.lastModified].join('|');if(queue.some(x=>x.key===key))continue;const el=document.createElement('li');el.className='item';const name=document.createElement('span');name.className='filename';name.textContent=file.webkitRelativePath||file.name;const status=document.createElement('span');status.className='state';const detail=document.createElement('span');detail.className='detail';const progress=document.createElement('progress');progress.max=100;progress.value=0;el.append(name,status,detail,progress);$('queue').append(el);const item={file,key,el,state:status,detail,progress};queue.push(item);state(item,file.size>1024**3||file.size===0?'error':'waiting',file.size>1024**3?'Larger than the 1 GB limit.':file.size===0?'This file is empty.':`${(file.size/1024**2).toFixed(1)} MB`);}if(ignored)$('service').textContent=`${ignored} other files ignored. Choose EPUB, PDF, or MOBI books.`;summary();}
function upload(item){return new Promise(resolve=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/library/upload');xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-Maha-Upload','1');xhr.setRequestHeader('X-File-Name',encodeURIComponent(item.file.name));xhr.timeout=15*60*1000;xhr.upload.onprogress=e=>{if(e.lengthComputable){item.progress.value=e.loaded/e.total*100;item.detail.textContent=`${Math.round(e.loaded/e.total*100)}% uploaded`;}};xhr.upload.onload=()=>state(item,'processing',/\.mobi$/i.test(item.file.name)?'Converting MOBI and preparing cover…':'Reading title and preparing cover…');xhr.onload=()=>{try{const r=JSON.parse(xhr.responseText);if(xhr.status===200&&['added','skipped'].includes(r.status)){item.bookId=r.id;state(item,r.status,r.title+(r.status==='added'?' · Uploaded successfully. AI sorting is queued; its final category will appear here.':''));}else state(item,'error',r.error||'Upload failed. Please retry.');}catch{state(item,'error',xhr.status===413?'The server rejected this file size.':'Upload failed. Please retry.');}resolve();};xhr.onerror=()=>{state(item,'error','Connection lost. Reconnect and retry this file.');resolve();};xhr.ontimeout=()=>{state(item,'error','The request timed out. Retry to check whether the book was added.');resolve();};state(item,'uploading','Starting upload…');xhr.send(item.file);});}
async function run(){if(running)return;running=true;stopping=false;$('stop').disabled=false;$('stop').textContent='Stop after this book';$('files').disabled=$('folder').disabled=true;summary();for(const item of queue){if(stopping)break;if(item.status==='waiting')await upload(item);}running=false;$('files').disabled=$('folder').disabled=false;summary();}
$('files').onchange=e=>{select(e.target.files);e.target.value='';};$('folder').onchange=e=>{select(e.target.files);e.target.value='';};$('start').onclick=run;$('retry').onclick=()=>{queue.filter(x=>x.status==='error').forEach(x=>state(x,'waiting','Ready to retry'));run();};$('stop').onclick=()=>{stopping=true;$('stop').disabled=true;$('stop').textContent='Stopping after this book…';};$('clear').onclick=()=>{queue=[];$('queue').replaceChildren();$('service').textContent='';summary();};const drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');select(e.dataTransfer.files);};window.addEventListener('beforeunload',e=>{if(running){e.preventDefault();e.returnValue='';}});fetch('/api/library/health').then(r=>{if(!r.ok)throw Error();return r.json();}).then(r=>{ready=r.ready&&(!window.MAHA_SESSION?.enabled||window.MAHA_SESSION.user?.role==='super');if(!r.mobi)$('service').textContent='MOBI conversion is not available yet. EPUB and PDF uploads are ready.';summary();}).catch(()=>{$('service').textContent='Book uploads are not connected yet. Finish installing the upload service on MAHA, then refresh.';});

$('choose-files').onclick=()=>$('files').click();$('choose-folder').onclick=()=>$('folder').click();

document.addEventListener('maha-session',()=>{if(window.MAHA_SESSION?.enabled&&window.MAHA_SESSION.user?.role!=='super'){ready=false;summary();$('service').textContent='A Super user account is needed to add books.';}});
setInterval(async()=>{const added=queue.filter(x=>x.bookId);if(!added.length)return;try{const response=await fetch('/api/library/books');if(!response.ok)return;const books=await response.json();for(const item of added){const book=books.find(b=>b.id===item.bookId);if(book)item.detail.textContent=book.title+' · '+(['queued','running'].includes(book.classification?.state)?'Uploaded; AI sorting in background':book.classification?.state==='review'?'Needs review: '+book.topic:'Filed under '+book.topic)+' · Search by title or filename in the library';}}catch{}},10000);
